#!/usr/bin/env node
/**
 * build-template.js — regenerate the full 18-layout Academic & Training template.
 *
 *   node build-template.js --palette teal     -o template-teal.pptx
 *   node build-template.js --palette burgundy -o template-burgundy.pptx
 *
 * The output is a reference deck: one slide per layout, English placeholder
 * content, Greek speaker notes explaining what each layout is for. Use it as a
 * visual index of the system, or as a starting file to overwrite slide by slide.
 *
 * For a real deck, do NOT edit this file — write your own script that requires
 * ./deck-lib.js and calls only the layouts your narrative needs.
 */

"use strict";

const path = require("path");
const { createDeck, NOTE } = require("./deck-lib");

/* ----------------------------- CLI parsing ----------------------------- */

function parseArgs(argv) {
  const args = { palette: "teal", out: null };
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--palette" || a === "-p") args.palette = argv[++i];
    else if (a === "--out" || a === "-o") args.out = argv[++i];
    else if (a === "--help" || a === "-h") args.help = true;
    else throw new Error(`Unknown argument: ${a}`);
  }
  if (args.help) {
    console.log(
      "Usage: node build-template.js [--palette burgundy|teal] [--out <file.pptx>]"
    );
    process.exit(0);
  }
  if (!["burgundy", "teal"].includes(args.palette)) {
    throw new Error(`--palette must be "burgundy" or "teal" (got "${args.palette}")`);
  }
  if (!args.out) args.out = `template-${args.palette}.pptx`;
  return args;
}

const args = parseArgs(process.argv);

const deck = createDeck({
  palette: args.palette,
  title: "Academic & Training Presentation Template",
  author: "Template",
  subject: "18-layout reference deck",
});

/* ------------------------------ 01 Cover ------------------------------ */

deck.cover({
  eyebrow: "PRESENTATION TEMPLATE",
  title: "The Title of Your Presentation",
  subtitle: "A concise, descriptive subtitle that sets the context",
  author: "Author Name",
  affiliation: "Affiliation / Department",
  date: "Month YYYY",
  notes: NOTE("Εξώφυλλο — θέμα, ομιλητής, ημερομηνία.", [
    "Πάντα το πρώτο slide.",
    "Τίτλος έως 8 λέξεις — τα υπόλοιπα στον υπότιτλο.",
    "Μην προσθέτεις logo πάνω από το accent rule.",
  ]),
});

/* --------------------------- 02 Instructions -------------------------- */

deck.howToUse({
  notes: NOTE("Meta-slide που εξηγεί το template σε όποιον ανοίξει το αρχείο.", [
    "Σβήσ' το πριν παραδώσεις ένα πραγματικό deck.",
    "Κράτα τους τίτλους στα ελληνικά για να ξεχωρίζει ως meta-slide.",
  ]),
});

/* ------------------------------ 03 Agenda ----------------------------- */

deck.agenda({
  eyebrow: "OVERVIEW",
  title: "Agenda",
  section: "Overview",
  items: [
    ["01", "Introduction & context", "Why this topic matters"],
    ["02", "Background & prior work", "What has already been established"],
    ["03", "Methodology", "How the study was conducted"],
    ["04", "Findings", "What the data shows"],
    ["05", "Implications", "What follows from the results"],
  ],
  notes: NOTE("Χάρτης της ομιλίας — 4 έως 6 ενότητες.", [
    "Πάνω από 6 γραμμές δεν χωράνε — ομαδοποίησε.",
    "Ο υπότιτλος κάθε γραμμής είναι μία φράση, όχι πρόταση.",
  ]),
});

/* -------------------------- 04 Section divider ------------------------ */

deck.sectionDivider({
  number: "01",
  label: "SECTION",
  title: "Introduction & context",
  subtitle: "A one-sentence framing of what this section covers.",
  section: "Introduction",
  notes: NOTE("Διαχωριστικό ενότητας — σηματοδοτεί αλλαγή θέματος.", [
    "Αύξησε τον αριθμό σε κάθε νέα ενότητα.",
    "Ίδια δομή σε όλα τα dividers — μην την παραλλάσσεις.",
  ]),
});

/* ----------------------- 05 Content + side callout -------------------- */

deck.contentCallout({
  eyebrow: "CONTEXT",
  title: "Content with hierarchy",
  section: "Introduction",
  bullets: [
    {
      text: "First main point stated as a claim",
      sub: ["Supporting detail or qualification", "Second supporting detail"],
    },
    { text: "Second main point", sub: ["Evidence or example"] },
    { text: "Third main point" },
  ],
  callout: {
    label: "Key insight",
    text: "The single most important thing the audience should take from this slide.",
  },
  notes: NOTE("Slide περιεχομένου με ιεραρχία — κύρια σημεία και sub-bullets.", [
    "Μέχρι 3 κύρια σημεία ανά slide.",
    "Κύρια σε bold ink, sub-bullets σε muted grey.",
    "Το callout κρατά ΈΝΑ μήνυμα, όχι περίληψη.",
  ]),
});

/* --------------------------- 06 Two-column ---------------------------- */

deck.twoColumn({
  eyebrow: "COMPARISON",
  title: "Two parallel ideas",
  section: "Background",
  left: {
    heading: "Theory",
    body: "A short paragraph presenting the first of two ideas of equal weight. Keep the length matched to the right column.",
    bullets: ["Claim one", "Claim two"],
  },
  right: {
    heading: "Practice",
    body: "The counterpart paragraph. Imbalance in length reads as bias, so match sentence count and rhythm.",
    bullets: ["Counterpart one", "Counterpart two"],
  },
  notes: NOTE("Δύο παράλληλες ιδέες ίσου βάρους (θεωρία vs πράξη).", [
    "Ίδιο μήκος και στις δύο στήλες.",
    "ΠΟΤΕ γραμμή κάτω από τους υπότιτλους — δείχνει AI-generated.",
  ]),
});

/* --------------------------- 07 Image + text -------------------------- */

deck.imageText({
  eyebrow: "METHOD",
  title: "Figure with interpretation",
  section: "Methodology",
  heading: "Study design",
  body: "Two sentences that tell the audience what to look at in the figure and why it matters.",
  bullets: ["Sample and setting", "Instruments used", "Analysis approach"],
  caption: "Figure 1. Study design overview. Source: Author, 2026.",
  notes: NOTE("Εικόνα/διάγραμμα με ερμηνευτικό κείμενο δίπλα.", [
    "Κάθε figure θέλει λεζάντα ΚΑΙ πηγή.",
    "Το κείμενο εξηγεί τι να δει το κοινό — δεν περιγράφει την εικόνα.",
  ]),
});

/* ------------------------- 08 Three-pillar grid ----------------------- */

deck.threePillars({
  eyebrow: "FRAMEWORK",
  title: "Three parallel concepts",
  section: "Methodology",
  pillars: [
    {
      num: "01",
      title: "First pillar",
      body: "Two sentences describing the first concept. Keep all three descriptions roughly the same length.",
    },
    {
      num: "02",
      title: "Second pillar",
      body: "The second concept, stated at the same level of abstraction as the first.",
    },
    {
      num: "03",
      title: "Third pillar",
      body: "The third concept. Together the three must be mutually exclusive and collectively exhaustive.",
    },
  ],
  notes: NOTE("Τρεις παράλληλες έννοιες (πυλώνες, διαστάσεις, βήματα).", [
    "Ακριβώς 3 — ούτε 2 ούτε 4.",
    "MECE: να μην επικαλύπτονται και να καλύπτουν το θέμα.",
    "Ίσο μήκος περιγραφών.",
  ]),
});

/* ----------------------------- 09 Big stat ---------------------------- */

deck.bigStat({
  eyebrow: "KEY FINDING",
  title: "Headline result",
  section: "Findings",
  stat: "87%",
  label: "of participants improved over the baseline",
  body: "Measured across 240 participants over a 12-week period. The effect held across all three cohorts.",
  source: "Source: Author, 2026. N = 240.",
  notes: NOTE("Ένα και μόνο ποσοτικό εύρημα σε πρώτο πλάνο.", [
    "Στρογγυλοί αριθμοί — 87%, όχι 87.34%.",
    "Πάντα ανάφερε μέγεθος δείγματος και χρονικό διάστημα.",
    "Ένα τέτοιο slide ανά deck.",
  ]),
});

/* -------------------------- 10 Before / After ------------------------- */

deck.beforeAfter({
  eyebrow: "CHANGE",
  title: "Before and after",
  section: "Findings",
  before: {
    label: "BEFORE",
    title: "The prior state",
    bullets: ["First condition", "Second condition", "Third condition"],
  },
  after: {
    label: "AFTER",
    title: "The new state",
    bullets: ["First improvement", "Second improvement", "Third improvement"],
  },
  notes: NOTE("Σύγκριση δύο καταστάσεων ή επιλογών.", [
    "Ίδιος αριθμός bullets και στις δύο κάρτες.",
    "Η δεξιά κάρτα έχει accent border — εκεί πάει το βλέμμα.",
  ]),
});

/* ---------------------------- 11 Pull quote --------------------------- */

deck.pullQuote({
  section: "Findings",
  quote:
    "A single authoritative sentence that reframes the problem and earns its own slide.",
  author: "Author Name",
  source: "Journal Name, 2026",
  notes: NOTE("Παράθεμα με κύρος που πλαισιώνει το επιχείρημα.", [
    "Έως 30 λέξεις.",
    "Ένα pull quote ανά deck — αλλιώς χάνει τη δύναμή του.",
  ]),
});

/* ------------------------------- 12 Chart ----------------------------- */

deck.chart({
  eyebrow: "EVIDENCE",
  title: "Quantitative trend",
  section: "Findings",
  seriesName: "Outcome",
  labels: ["Baseline", "Week 4", "Week 8", "Week 12"],
  values: [42, 58, 71, 87],
  panelLabel: "What this shows",
  interpretation:
    "Improvement is monotonic across all four measurement points, with the steepest gain between baseline and week 4.",
  source: "Source: Author, 2026.",
  notes: NOTE("Ποσοτική τεκμηρίωση με ερμηνεία δίπλα.", [
    "ΠΟΤΕ chart χωρίς το πάνελ ερμηνείας δεξιά.",
    "Ένα series ανά chart — αλλιώς χάνεται το μήνυμα.",
  ]),
});

/* ----------------------------- 13 Timeline ---------------------------- */

deck.timeline({
  eyebrow: "PROCESS",
  title: "Four-step procedure",
  section: "Methodology",
  steps: [
    { title: "Plan", body: "Define the question and the design" },
    { title: "Collect", body: "Gather data from all sources" },
    { title: "Analyze", body: "Test the hypotheses" },
    { title: "Share", body: "Publish and disseminate" },
  ],
  notes: NOTE("Ακολουθία 3–5 διακριτών βημάτων.", [
    "Οι τίτλοι είναι ρήματα μίας λέξης.",
    "Πάνω από 5 βήματα → σπάσ' το σε δύο slides.",
  ]),
});

/* ------------------------------- 14 Table ----------------------------- */

deck.table({
  eyebrow: "RESULTS",
  title: "Results across conditions",
  section: "Findings",
  headers: ["Condition", "N", "Mean", "SD", "p"],
  rows: [
    ["Control", { text: "80", muted: true }, "42.1", { text: "6.4", muted: true }, "—"],
    [
      "Treatment A",
      { text: "80", muted: true },
      { text: "58.7", significant: true },
      { text: "5.9", muted: true },
      { text: "< .01", significant: true },
    ],
    ["Treatment B", { text: "80", muted: true }, "49.3", { text: "7.1", muted: true }, ".08"],
  ],
  source: "Source: Author, 2026. Bold values are significant at p < .01.",
  notes: NOTE("Πολυμεταβλητά ποσοτικά αποτελέσματα.", [
    "Το accent χρώμα σημαίνει στατιστική σημαντικότητα — όχι διακόσμηση.",
    "Δευτερεύουσες τιμές (N, SD) σε muted.",
  ]),
});

/* ----------------------------- 15 Takeaways --------------------------- */

deck.takeaways({
  eyebrow: "SUMMARY",
  title: "Key takeaways",
  section: "Implications",
  items: [
    { title: "The first thing to remember", body: "One line that restates the core finding." },
    { title: "The second thing to remember", body: "One line on what it changes." },
    { title: "What to do next", body: "An actionable implication — not another summary point." },
  ],
  notes: NOTE("Τα 3 πράγματα που πρέπει να θυμάται το κοινό.", [
    "Ακριβώς 3.",
    "Το τρίτο πρέπει να είναι actionable — τι να κάνει το κοινό.",
  ]),
});

/* ---------------------------- 16 References --------------------------- */

deck.references({
  section: "Appendix",
  entries: [
    [
      { text: "Author, A. A., & Author, B. B. (2023). Title of the article in sentence case. " },
      { text: "Journal Name, 12", italic: true },
      { text: "(3), 45–67. https://doi.org/10.0000/example" },
    ],
    [
      { text: "Author, C. C. (2024). " },
      { text: "Title of the book in italics", italic: true },
      { text: ". Publisher." },
    ],
    [
      { text: "Author, D. D. (2025). Conference paper title. In " },
      { text: "Proceedings of the Conference", italic: true },
      { text: " (pp. 101–115). Publisher." },
    ],
  ],
  notes: NOTE("Βιβλιογραφία σε APA 7.", [
    "Έως 4 εγγραφές ανά slide — μετά δεύτερο slide.",
    "Ποτέ μη μικραίνεις τη γραμματοσειρά για να χωρέσουν.",
  ]),
});

/* ------------------------------- 17 Q&A ------------------------------- */

deck.qa({
  section: "End",
  headline: "Q&A",
  thanks: "Thank you.",
  contact: ["Author Name", "author@institution.edu", "@handle · institution.edu/author"],
  notes: NOTE("Slide κλεισίματος που μένει στην οθόνη στις ερωτήσεις.", [
    "Πάντα με στοιχεία επικοινωνίας — γι' αυτό υπάρχει.",
    "Πάντα τελευταίο slide περιεχομένου.",
  ]),
});

/* -------------------------- 18 Design tokens -------------------------- */

deck.designTokens({
  section: "Appendix",
  notes: NOTE("Εσωτερικό φύλλο αναφοράς με τα design tokens.", [
    "Κράτα το για συνεργάτες, σβήσ' το για το κοινό.",
    "Ενημέρωσέ το αν αλλάξεις παλέτα.",
  ]),
});

/* ------------------------------- write -------------------------------- */

deck
  .save(args.out)
  .then((f) => console.log(`Saved: ${path.resolve(f)}  (18 slides, palette: ${args.palette})`))
  .catch((err) => {
    console.error("Failed to write deck:", err.message);
    process.exit(1);
  });
